namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // 输入 x: [N, C, H, W], 权重 w: [Cout, Cin, Kh, Kw]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);
    gert::Shape* y_shape = context->GetOutputShape(0);

    int64_t n = x_shape->GetDim(0);
    int64_t h = x_shape->GetDim(2);
    int64_t w = x_shape->GetDim(3);
    int64_t cout = w_shape->GetDim(0);
    int64_t kh = w_shape->GetDim(2);
    int64_t kw = w_shape->GetDim(3);

    // 默认参数
    int64_t pad_t = 0, pad_b = 0, pad_l = 0, pad_r = 0;
    int64_t stride_h = 1, stride_w = 1;
    int64_t dil_h = 1, dil_w = 1;

    int64_t ho = ( (h + pad_t + pad_b - dil_h * (kh - 1) - 1) / stride_h ) + 1;
    int64_t wo = ( (w + pad_l + pad_r - dil_w * (kw - 1) - 1) / stride_w ) + 1;

    std::vector<int64_t> out_dims = {n, cout, ho, wo};
    y_shape->SetDimNum(4);
    for (size_t i = 0; i < out_dims.size(); ++i) {
        y_shape->SetDim(i, out_dims[i]);
    }
    return GRAPH_SUCCESS;
}

