#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline std::vector<int64_t> infer_conv2d_output_shape(
    const at::Tensor& x, const at::Tensor& w,
    int64_t pad_t=0, int64_t pad_b=0, int64_t pad_l=0, int64_t pad_r=0,
    int64_t stride_h=1, int64_t stride_w=1, int64_t dil_h=1, int64_t dil_w=1)
{
    // x: [N, C, H, W], w: [Cout, Cin, Kh, Kw]
    auto N = x.size(0);
    auto H = x.size(2);
    auto W = x.size(3);
    auto Cout = w.size(0);
    auto Kh = w.size(2);
    auto Kw = w.size(3);
    int64_t Ho = ( (H + pad_t + pad_b - dil_h * (Kh - 1) - 1) / stride_h ) + 1;
    int64_t Wo = ( (W + pad_l + pad_r - dil_w * (Kw - 1) - 1) / stride_w ) + 1;
    return {N, Cout, Ho, Wo};
}

at::Tensor conv_standard_2d_asymmetric_input_asymmetric_kernel_custom_impl_npu(
    const at::Tensor& x, const at::Tensor& w)
{
    // 默认 stride=(1,1), padding=(0,0,0,0), dilation=(1,1), groups=1
    auto out_sizes = infer_conv2d_output_shape(x, w);
    at::Tensor result = at::empty(out_sizes, x.options());
    EXEC_NPU_CMD(aclnnConvStandard2dAsymmetricInputAsymmetricKernelCustom, x, w, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_standard_2d_asymmetric_input_asymmetric_kernel_custom", &conv_standard_2d_asymmetric_input_asymmetric_kernel_custom_impl_npu);
}

